(() => {
  "use strict";

  const TEXTS = ["På morgonen vaknar Amir när alarmet ringer. Han går upp, bäddar sängen och öppnar gardinen. Sedan äter han en smörgås och dricker ett glas mjölk. Innan han går till skolan kontrollerar han att böckerna och pennan ligger i väskan.", "Efter skolan går Sara hem tillsammans med sin kompis. De pratar om vad som hände under dagen och skrattar åt en rolig sak från lektionen. När Sara kommer hem tar hon av sig jackan, gör en smörgås och sätter sig en stund innan hon börjar med läxan.", "Det regnar ute när Leo ska gå till affären med sin pappa. Han tar på sig stövlar, jacka och huva. I affären köper de bröd, mjölk och frukt. Leo hjälper till att bära en påse hem och ställer sedan varorna på köksbordet.", "Maja vaknar lite före väckarklockan och ligger kvar en kort stund. Sedan går hon upp, borstar tänderna och klär på sig. I köket äter hon yoghurt och en smörgås. När hon är klar tar hon sin väska och går mot skolan.", "På lördagen träffar Adam sina vänner på fotbollsplanen. Först värmer de upp och passar bollen mellan varandra. Sedan spelar de en kort match. Efteråt är Adam trött men nöjd. Han dricker vatten, säger hej då till sina vänner och går hem.", "Nora går till biblioteket efter skolan eftersom hon vill hitta en ny bok. Hon tittar på flera hyllor och väljer till slut en bok om djur. Hon sätter sig vid ett bord och läser några sidor. Innan hon går hem lånar hon boken i kassan.", "I dag hjälper Elias sin mamma att laga middag. Han sköljer grönsaker och skär gurka i små bitar. Mamman lagar resten av maten medan Elias dukar bordet. När allt är klart sätter sig familjen tillsammans och äter. Elias tycker att maten blev väldigt god.", "Solen skiner när Lina går ut efter lunch. Hon tar med en flaska vatten och går en lugn promenad genom området. I parken ser hon barn som leker och en hund som springer efter en boll. Efter en stund sätter hon sig på en bänk och vilar.", "På kvällen gör Samir sig redo för nästa skoldag. Han tittar på sitt schema och packar rätt böcker i väskan. Sedan lägger han fram kläder på en stol. Innan han går och lägger sig borstar han tänderna och ställer alarmet på rätt tid.", "Emma väntar på bussen utanför skolan. Det är lite kallt, så hon stoppar händerna i fickorna. Efter några minuter kommer bussen. Emma sätter sig vid fönstret och tittar ut under resan. När hon ser sin hållplats trycker hon på stoppknappen.", "I klassrummet får eleverna en ny uppgift av läraren. Ali läser frågan två gånger för att vara säker på att han förstår. Sedan börjar han skriva sitt svar i lugn takt. När han är klar läser han igenom texten och rättar ett ord som blev fel.", "Mira går till affären för att köpa några saker till frukosten. Hon behöver mjölk, bröd, ost och äpplen. Hon hittar allt på sin lista och går sedan till kassan. Efter att hon har betalat lägger hon varorna i en påse och går hem.", "Det är kallt ute på morgonen och marken är lite hal. Joel tar på sig mössa, vantar och en varm jacka. Han går försiktigt på vägen till skolan. När han kommer fram hänger han av sig ytterkläderna och går in till sin första lektion.", "Efter middagen hjälper Alma till hemma. Hon tar bort tallrikar, glas och bestick från bordet. Sedan ställer hon sakerna i diskmaskinen och torkar av bordet med en trasa. När köket är klart går hon till sitt rum och fortsätter med det hon höll på med.", "Yara märker i skolan att hon har glömt sin penna hemma. Hon frågar sin kompis om hon kan få låna en under lektionen. Kompisen säger ja och ger henne en blå penna. Efter lektionen lämnar Yara tillbaka pennan och tackar för hjälpen.", "På rasten går Omar ut på skolgården med sina vänner. De pratar en stund och börjar sedan spela med en boll. Omar passar bollen till sin kompis och försöker göra mål. När klockan ringer går de in igen och sätter sig i klassrummet.", "Hanna är trött och törstig efter träningen. Hon fyller sin vattenflaska och sätter sig på en bänk en stund. Hon dricker långsamt och pratar lite med en kompis. När hon har vilat packar hon sina saker och går hem för att duscha.", "Karim ska träffa sin vän klockan fyra på eftermiddagen. Han tittar på klockan hemma och går iväg i god tid. På vägen lyssnar han på musik. De möts utanför en butik och bestämmer sedan att de ska gå en promenad tillsammans.", "I dag lär sig Sofia ett nytt svenskt ord i skolan. Hon läser ordet högt flera gånger och frågar läraren vad det betyder. Sedan skriver hon en enkel mening med ordet. På kvällen försöker hon komma ihåg ordet igen utan att titta i sitt block.", "David städar sitt rum på söndagen. Först plockar han upp kläder från golvet och lägger dem på rätt plats. Sedan ställer han böckerna på hyllan och bäddar sängen. Till sist dammsuger han golvet. När allt är klart känns rummet mycket lugnare.", "Efter skolan vill Amina vila en liten stund innan hon gör något annat. Hon sätter sig i soffan och lyssnar på musik. Efter ungefär tjugo minuter känner hon sig piggare. Då hämtar hon sin väska, öppnar datorn och börjar arbeta med en skoluppgift.", "I parken finns många träd, en lekplats och flera bänkar. Noah går dit med sin lillasyster efter lunch. Hon leker en stund medan Noah sitter nära och tittar. Sen går de tillsammans runt parken. När de blir trötta går de hem igen.", "Fatima ska laga pasta till middag och börjar med att fylla en kastrull med vatten. När vattnet kokar lägger hon i pastan. Under tiden gör hon en enkel sås. När maten är färdig dukar hon bordet och ropar på resten av familjen.", "På väg till skolan ser Erik att en cykel har ramlat på marken. Han stannar och ställer upp cykeln igen så att ingen ska snubbla på den. Sedan fortsätter han gå. Han kommer fram i tid och berättar för sin kompis vad som hände.", "Lina öppnar fönstret i sitt rum för att få in frisk luft. Sedan sätter hon sig vid skrivbordet med en bok och ett glas vatten. Hon läser några sidor i lugn takt. När hon är klar stänger hon boken och skriver ner ett ord hon vill komma ihåg.", "I dag har klassen idrott på förmiddagen. Eleverna byter om och går tillsammans till hallen. Läraren visar först en enkel övning. Sedan får alla prova själva. Efter lektionen byter de om igen och går tillbaka till klassrummet för nästa lektion.", "Mariam får ett meddelande från sin vän efter skolan. Vännen frågar om de ska träffas en stund på eftermiddagen. Mariam tittar på tiden och svarar att det passar bra. De bestämmer en plats och en tid så att båda vet var de ska ses.", "Anton är hungrig när han kommer hem från skolan. Han tvättar händerna och går till köket. Där tar han ett äpple och gör en smörgås. Sedan häller han upp ett glas vatten och sätter sig vid bordet. Efter maten känner han sig piggare.", "Det blåser mycket ute när Selma går hem från skolan. Hon håller i sin mössa så att den inte flyger bort. När hon kommer in hänger hon jackan på en krok och ställer skorna vid dörren. Sedan går hon till köket för att ta något att äta.", "På kvällen tittar familjen på en film tillsammans. De sitter i soffan och har en stor filt över benen. Under filmen äter de lite popcorn. När filmen är slut pratar de om vilken del de tyckte bäst om. Sedan börjar alla göra sig redo för natten.", "I skolan ska Benjamin arbeta tillsammans med en kompis. De läser uppgiften och bestämmer vem som ska göra vad. Benjamin skriver några meningar medan kompisen letar efter information. Till slut läser de igenom allt tillsammans och ändrar en mening som blev otydlig.", "Moa behöver köpa en present till sin vän som fyller år. Hon går runt i några butiker och tittar på olika saker. Först kan hon inte bestämma sig. Till slut hittar hon en liten present som hon tror att vännen kommer att gilla och köper den.", "På morgonen hittar Isak inte sina nycklar. Han letar på bordet, i jackan och bredvid sängen. Han börjar bli lite stressad men fortsätter leta lugnt. Till slut ser han nycklarna bredvid sin ryggsäck. Han tar dem och hinner ändå gå hemifrån i tid.", "Ella tränar på att läsa svenska varje dag. Hon börjar med en kort text och läser långsamt rad för rad. När ett ord känns svårt stannar hon och provar igen. Efteråt läser hon samma mening en gång till. Då märker hon att det går lite lättare.", "Ahmed går till tandläkaren på eftermiddagen. När han kommer fram säger han sitt namn i receptionen och sätter sig i väntrummet. Efter en liten stund blir det hans tur. Besöket går bra. När han är klar tar han på sig jackan och går hem.", "I dag ska Tilda baka tillsammans med sin syster. De tar fram mjöl, ägg, socker och en skål. Först läser de receptet noggrant. Sedan blandar de allt steg för steg. När kakan är färdig låter de den svalna innan de smakar en bit.", "På bussen ser Hassan en ledig plats nära fönstret. Han sätter sig och tar av sig ryggsäcken så att den inte är i vägen. Under resan tittar han ut och lyssnar på musik. När hans hållplats närmar sig trycker han på stoppknappen.", "Julia får tillbaka ett prov i skolan. Hon tittar först på resultatet och sedan på frågorna hon svarade fel på. Hon försöker förstå vad som blev fel. Efter lektionen frågar hon läraren om en uppgift. Läraren förklarar och Julia skriver ner svaret.", "På söndagen ringer Elias till sin mormor. De pratar om hur veckan har varit och vad de har gjort. Mormor berättar om sin trädgård och Elias berättar om skolan. Innan de lägger på bestämmer de att de ska höras igen nästa helg.", "Nadia ska tvätta sina kläder under eftermiddagen. Hon sorterar först de ljusa och mörka kläderna. Sedan lägger hon en tvätt i maskinen och startar den. När tvätten är klar tar hon ut kläderna och hänger upp dem så att de kan torka.", "Victor har lite bråttom till skolan men stannar ändå vid ett rödljus. Han väntar tills lampan blir grön innan han går över vägen. På andra sidan fortsätter han i snabb takt. Han kommer fram precis innan lektionen börjar och sätter sig på sin plats.", "På lunchen väljer Maja ris, kyckling och grönsaker. Hon tar ett glas vatten och sätter sig med sina vänner. De äter och pratar om vad de ska göra efter skolan. När de är klara lämnar de sina brickor och går tillbaka mot klassrummet.", "Oskar vill komma ihåg det viktigaste från lektionen. Därför skriver han några korta anteckningar i sitt block medan läraren pratar. Hemma läser han igenom sina anteckningar en gång till. Han markerar två saker som han behöver träna lite mer på.", "I dag är himlen grå men det regnar inte ännu. Sara bestämmer sig ändå för att lägga ett litet paraply i väskan. Under dagen börjar det regna när hon ska gå hem. Hon blir glad att hon tog med paraplyet och kan gå hem utan att bli blöt.", "Efter träningen känner sig Adam trött i benen. Han går hem i lugn takt och tar en dusch. Sedan äter han något och dricker ett stort glas vatten. Han sätter sig i soffan en stund för att vila. Efter en liten stund känner han sig bättre.", "I korridoren tappar Leo några papper på golvet när han öppnar sin väska. En annan elev stannar och hjälper honom att plocka upp dem. Leo säger tack och lägger papperen i en mapp. Sedan går de åt varsitt håll till sina lektioner.", "På morgonen kontrollerar Nora sin skolväska innan hon går hemifrån. Hon ser att datorn, laddaren, blocket och pennorna är med. Sedan tar hon på sig jackan och skorna. När allt är klart går hon ut och börjar gå mot skolan.", "I affären jämför Karim två olika paket med samma sorts mat. Han tittar på priset och hur mycket varje paket innehåller. Det ena är billigare men det andra är större. Efter att ha tänkt en stund väljer han det som passar bäst och går vidare.", "Alva vill lära sig ett nytt recept till middagen. Hon läser först igenom hela receptet och tar fram allt hon behöver. Sedan börjar hon laga maten steg för steg. När hon är osäker läser hon samma rad igen. Till slut är maten färdig och doftar gott.", "När skoldagen är slut går Yasin till sitt skåp. Han tar sin jacka och lägger böckerna han behöver i väskan. Sedan stänger han skåpet och går mot utgången. Utanför skolan väntar en vän och de går en bit tillsammans på vägen hem.", "På kvällen hörs regnet mot fönstret. Amir sitter vid bordet och ritar medan hans syster läser en bok. Det är lugnt i rummet. Efter en stund hämtar Amir ett glas vatten och fortsätter rita. När han är klar visar han bilden för sin syster.", "Sofia ska skicka ett meddelande till sin lärare om en uppgift. Hon skriver först vad hon undrar över. Sedan läser hon igenom meddelandet för att se att det är tydligt och vänligt. När allt ser bra ut trycker hon på skicka och väntar på svar.", "Efter frukosten fyller Omar sin vattenflaska i köket. Han lägger den i ryggsäcken tillsammans med sitt block och sin dator. Sedan tar han på sig jackan och kontrollerar att han har nycklarna. När allt är klart går han hemifrån mot skolan.", "I dag ska eleverna läsa högt två och två. De turas om att läsa några meningar från en enkel text. Om någon fastnar på ett ord väntar den andra och hjälper till. När de har läst klart pratar de kort om vad texten handlade om.", "Samir tittar ut genom fönstret och ser stora snöflingor falla. Han tar på sig varma byxor, jacka, mössa och vantar innan han går ut. Marken är redan vit. På vägen ser han några barn som bygger en liten snögubbe nära huset.", "Emma har en skoluppgift som först känns svår. Hon läser instruktionen långsamt och börjar med den första delen. Sedan tar hon en sak i taget. Efter en stund har hon gjort mer än hon trodde. Hon fortsätter tills hon känner att hon förstår uppgiften bättre.", "Efter middagen läser Lina några sidor i en bok. Hon hittar ett ord som hon inte förstår och stannar upp. Först försöker hon förstå ordet från meningen. Sedan frågar hon vad det betyder. När hon vet svaret läser hon meningen en gång till.", "Maja vill hålla bättre ordning på sin vecka. Hon tar fram ett papper och skriver ner några saker hon behöver göra. Sedan väljer hon vad som är viktigast och börjar med en enkel uppgift. När den är klar stryker hon den från listan.", "Nora lånar en penna av sin vän under första lektionen. Senare märker hon att pennan fortfarande ligger i hennes pennfodral. Hon går direkt till vännen och lämnar tillbaka den. Vännen ler och säger att det inte var någon fara. Nora säger tack igen.", "I skolan ska Amina hålla en kort presentation inför klassen. Innan hon börjar tittar hon snabbt på sina stödord. Sedan pratar hon lugnt och försöker titta upp ibland. När presentationen är klar känner hon sig lättad och nöjd över att hon vågade göra den."];
  const STORAGE_KEY = "mikal_skriva_text_history_v2";

  function norm(v) {
    return String(v || "").replace(/\s+/g, " ").trim();
  }

  function history() {
    try {
      const h = JSON.parse(localStorage.getItem(STORAGE_KEY) || "[]");
      return Array.isArray(h) ? h.filter(Number.isInteger) : [];
    } catch {
      return [];
    }
  }

  function freshIndex() {
    const h = history();
    const blocked = new Set(h.slice(-12));
    let choices = TEXTS.map((_, i) => i).filter(i => !blocked.has(i));
    if (!choices.length) choices = TEXTS.map((_, i) => i);

    let index = choices[Math.floor(Math.random() * choices.length)];
    const last = h.length ? h[h.length - 1] : -1;

    if (index === last && choices.length > 1) {
      index = choices.find(i => i !== last);
    }

    h.push(index);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(h.slice(-14)));
    return index;
  }

  function findSource() {
    const selectors = [
      "#writingText", "#sourceText", "#textToCopy", "#copyText",
      "[data-writing-text]", ".writing-text", ".source-text",
      ".text-to-write", ".writing-source", ".copy-source"
    ];

    for (const s of selectors) {
      const el = document.querySelector(s);
      if (el && norm(el.textContent).length >= 20) return el;
    }

    const old = [...document.querySelectorAll("p,div,article")]
      .find(el =>
        norm(el.textContent).startsWith("I går gick Lina till biblioteket")
        && !el.querySelector("textarea,input,button")
      );

    if (old) return old;

    const label = [...document.querySelectorAll("p,div,span,h2,h3,h4")]
      .find(el => norm(el.textContent).toUpperCase() === "TEXT ATT SKRIVA");

    if (!label) return null;

    let box = label.parentElement;

    for (let level = 0; box && level < 5; level++, box = box.parentElement) {
      const labelTop = label.getBoundingClientRect().top;

      const candidates = [...box.querySelectorAll("p,div,span")]
        .filter(el => {
          if (el === label || el.contains(label)) return false;
          if (el.querySelector("textarea,input,button")) return false;

          const text = norm(el.textContent);
          if (text.length < 20 || text.length > 450) return false;

          const upper = text.toUpperCase();
          if (
            upper.includes("30 MINUTERS TRÄNING") ||
            upper.includes("LÄS OCH SKRIV SAMMA TEXT") ||
            upper.includes("SKRIV TEXTEN HÄR")
          ) return false;

          return el.getBoundingClientRect().top >= labelTop;
        })
        .sort((a, b) =>
          (a.childElementCount - b.childElementCount) ||
          (norm(a.textContent).length - norm(b.textContent).length)
        );

      if (candidates.length) return candidates[0];
    }

    return null;
  }

  function apply(index) {
    const el = findSource();
    if (!el) {
      console.warn("[Skriva V2] Kunde inte hitta texten att skriva av.");
      return false;
    }

    el.textContent = TEXTS[index];
    el.dataset.mikalWritingSource = "true";
    el.style.fontSize = "clamp(16px, 1.25vw, 18px)";
    el.style.lineHeight = "1.75";
    el.style.maxWidth = "74ch";
    return true;
  }

  function newText() {
    const i = freshIndex();
    apply(i);
    setTimeout(() => apply(i), 120);
    setTimeout(() => apply(i), 420);
  }

  function removeSidebar() {
    const marker = [...document.querySelectorAll("body *")]
      .find(el => norm(el.textContent).toUpperCase() === "SKRIVTRÄNING");

    if (!marker) return false;

    let node = marker;

    for (let level = 0; node && level < 6; level++, node = node.parentElement) {
      const t = norm(node.innerText || node.textContent).toUpperCase();

      if (
        t.includes("SKRIVTRÄNING") &&
        t.includes("KOPIERA TEXT") &&
        t.includes("LÄS OCH SKRIV AV") &&
        t.length < 280
      ) {
        const parent = node.parentElement;
        node.remove();

        if (parent) {
          parent.classList.add("mikal-writing-single-column");
          parent.style.display = "block";
          parent.style.gridTemplateColumns = "minmax(0,1fr)";

          [...parent.children].forEach(child => {
            child.style.width = "100%";
            child.style.maxWidth = "none";
            child.style.flex = "1 1 100%";
          });
        }

        return true;
      }
    }

    return false;
  }

  function addStyles() {
    if (document.getElementById("mikalSkrivaV2Styles")) return;

    const style = document.createElement("style");
    style.id = "mikalSkrivaV2Styles";
    style.textContent = `
      body.mikal-skriva-v2 .mikal-writing-single-column {
        width:100% !important;
        max-width:none !important;
        gap:0 !important;
      }

      body.mikal-skriva-v2 textarea {
        width:100% !important;
        max-width:100% !important;
        min-height:170px;
        font-size:clamp(16px,1.2vw,18px) !important;
        line-height:1.7 !important;
      }

      @media (max-width:1100px) {
        body.mikal-skriva-v2 .mikal-writing-single-column {
          display:block !important;
          grid-template-columns:minmax(0,1fr) !important;
        }

        body.mikal-skriva-v2 .mikal-writing-single-column > * {
          width:100% !important;
          max-width:none !important;
          margin-left:0 !important;
          margin-right:0 !important;
        }
      }

      @media (max-width:760px) {
        body.mikal-skriva-v2 [data-mikal-writing-source="true"] {
          font-size:16px !important;
          line-height:1.72 !important;
        }

        body.mikal-skriva-v2 textarea {
          min-height:150px !important;
          font-size:16px !important;
        }
      }
    `;

    document.head.appendChild(style);
  }

  function init() {
    document.body.classList.add("mikal-skriva-v2");
    addStyles();
    removeSidebar();
    newText();

    document.addEventListener("click", event => {
      const button = event.target.closest("button,a");
      if (!button) return;

      if (norm(button.textContent).toUpperCase().includes("NY TEXT")) {
        const i = freshIndex();
        setTimeout(() => apply(i), 50);
        setTimeout(() => apply(i), 180);
        setTimeout(() => apply(i), 420);
      }
    }, true);

    setTimeout(removeSidebar, 250);
    setTimeout(removeSidebar, 700);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init, {once:true});
  } else {
    init();
  }
})();
